        ptr.addr() != 0 ==> user_perm.provenance() == ptr@.provenance,
        ptr.addr() != 0 ==> ptr == user_dealloc.unwrap().ptr(),
        ptr.addr() != 0 ==> old(local).inst() == user_dealloc.unwrap().inst()
